// HasTeam applies the HasEdge predicate on the "team" edge.
func HasTeam() predicate.TeamUsageModelDaily {
	return predicate.TeamUsageModelDaily(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TeamTable, TeamColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTeamWith applies the HasEdge predicate on the "team" edge with a given conditions (other predicates).
func HasTeamWith(preds ...predicate.Team) predicate.TeamUsageModelDaily {
	return predicate.TeamUsageModelDaily(func(s *sql.Selector) {
		step := newTeamStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TeamUsageModelDaily) predicate.TeamUsageModelDaily {
	return predicate.TeamUsageModelDaily(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TeamUsageModelDaily) predicate.TeamUsageModelDaily {
	return predicate.TeamUsageModelDaily(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TeamUsageModelDaily) predicate.TeamUsageModelDaily {
	return predicate.TeamUsageModelDaily(sql.NotPredicates(p))
}
